import { makeAutoObservable } from "mobx";

class CartStore {
  cart = [];

  constructor() {
    makeAutoObservable(this);
  }

  updateQuantity(itemId, newQuantity) {
    const item = this.cart.find((cartItem) => cartItem.id === itemId);
    if (item) {
      item.quantity = newQuantity;
      const addOnTotal = item.addOn?.reduce((sum, addOn) => sum + (addOn.price * newQuantity), 0) || 0;
      item.totalPrice = (item.price * newQuantity) + addOnTotal;
    }
  }

  updateAddOnQuantity(itemId, addOnId, newQuantity) {
    const item = this.cart.find((cartItem) => cartItem.id === itemId);
    if (item) {
      const addOn = item.addOn?.find((addOn) => addOn.id === addOnId);
      if (addOn) {
        addOn.quantity = newQuantity;
        addOn.totalPrice = addOn.price * newQuantity;
        this.updateQuantity(itemId, item.quantity);
      }
    }
  }

  addToCart(item) {
    const existingItem = this.cart.find((cartItem) => cartItem.id === item.id);
    if (existingItem) {
      this.updateQuantity(item.id, existingItem.quantity + 1);
    } else {
      const itemWithAddOn = {
        ...item,
        quantity: 1,
        addOn: item.addOn ? item.addOn.map((addon) => ({
          ...addon,
          quantity: 1,
          totalPrice: addon.price,
        })) : [],
      };

      itemWithAddOn.totalPrice = itemWithAddOn.price + itemWithAddOn.addOn.reduce((sum, addOn) => sum + addOn.totalPrice, 0);

      this.cart.push(itemWithAddOn);
    }
  }

  removeFromCart(itemId) {
    this.cart = this.cart.filter((item) => item.id !== itemId);
  }

  clearCart() {
    this.cart = [];
  }

  get totalPrice() {
    return this.cart.reduce((total, item) => total + (item.totalPrice || 0), 0);
  }

  get totalAddOns() {
    return this.cart.reduce((total, item) => {
      const addOnCount = item.addOn?.reduce((sum, addOn) => sum + addOn.quantity, 0) || 0;
      return total + addOnCount;
    }, 0);
  }
}

const cartStore = new CartStore();
export { cartStore };
